#!/usr/bin/env bash
# Question 13: PersistentVolumeClaim ${Q13_NAME}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q13_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q13_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q13_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: v1
kind: PersistentVolume
metadata:
  name: ${Q13_NAME}-pv
spec:
  capacity: { storage: 1Gi }
  accessModes: [ReadWriteOnce, ReadWriteMany]
  persistentVolumeReclaimPolicy: Retain
  storageClassName: manual
  hostPath:
    path: /srv/${Q13_NAME}
    type: DirectoryOrCreate
EOF
